var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var OFFICIAL = 1847.32;
var ev = root.querySelector('.hfd-navhdr-ev');
var ed = root.querySelector('.hfd-navhdr-ed');
var est = 1851.06;
function fmt(n) {
  var s = n.toFixed(2).split('.');
  return s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + s[1];
}
Array.prototype.forEach.call(root.querySelectorAll('.hfd-navhdr-tile'), function (t, i) {
  var v = parseFloat(t.getAttribute('data-v')), mx = parseFloat(t.getAttribute('data-max'));
  var b = t.querySelector('.hfd-navhdr-tb');
  var w = (Math.min(Math.abs(v) / mx, 1) * 100).toFixed(1) + '%';
  if (reduce) { b.style.width = w; return; }
  setTimeout(function () { if (root.isConnected) b.style.width = w; }, 90 + i * 120);
});
var tid = setInterval(function () {
  if (!root.isConnected) { clearInterval(tid); return; }
  est += (Math.random() - 0.47) * 1.8;
  if (est > OFFICIAL * 1.0125) est = OFFICIAL * 1.0125;
  if (est < OFFICIAL * 0.9935) est = OFFICIAL * 0.9935;
  var d = (est / OFFICIAL - 1) * 100;
  ev.textContent = fmt(est);
  ed.textContent = (d >= 0 ? '+' : '-') + Math.abs(d).toFixed(2) + '%';
  ed.className = 'hfd-navhdr-ed ' + (d >= 0 ? 'hfd-navhdr-up' : 'hfd-navhdr-dn');
  if (reduce) return;
  ev.classList.remove('hfd-navhdr-fl');
  void ev.offsetWidth;
  ev.classList.add('hfd-navhdr-fl');
}, 1500);

