var SCALE = 40;
var body = root.querySelector('.hfd-grossnet-body');
var btn = root.querySelector('.hfd-grossnet-sort');
var rd = root.querySelector('.hfd-grossnet-rd');
var rows = Array.prototype.slice.call(root.querySelectorAll('.hfd-grossnet-row'));
var MODES = ['GROSS', 'NET', 'LONG', 'SHORT'];
var mi = 0;
function d(r, k) { return parseFloat(r.getAttribute('data-' + k)); }
function net(r) { return d(r, 'l') - d(r, 'h'); }
function gross(r) { return d(r, 'l') + d(r, 'h'); }
function sg(v, p) { return (v >= 0 ? '+' : '-') + Math.abs(v).toFixed(p); }
var TOT = { l: 0, s: 0 };
rows.forEach(function (r) { TOT.l += d(r, 'l'); TOT.s += d(r, 'h'); });
var TG = TOT.l + TOT.s;
function paint() {
  rows.forEach(function (r, i) {
    var n = net(r), g = gross(r);
    r.classList.toggle('hfd-grossnet-pos', n >= 0);
    r.classList.toggle('hfd-grossnet-neg', n < 0);
    r.querySelector('.hfd-grossnet-nv').textContent = sg(n, 1);
    r.querySelector('.hfd-grossnet-gv').textContent = g.toFixed(1);
    var bs = r.querySelector('.hfd-grossnet-bs'), bl = r.querySelector('.hfd-grossnet-bl');
    var mk = r.querySelector('.hfd-grossnet-mk');
    setTimeout(function () {
      if (!root.isConnected) return;
      bs.style.width = (Math.min(d(r, 'h') / SCALE, 1) * 50).toFixed(2) + '%';
      bl.style.width = (Math.min(d(r, 'l') / SCALE, 1) * 50).toFixed(2) + '%';
      mk.style.left = (50 + Math.max(-1, Math.min(1, n / SCALE)) * 50).toFixed(2) + '%';
    }, 40 + i * 45);
  });
  root.querySelector('.hfd-grossnet-g').textContent = TG.toFixed(1) + '%';
  root.querySelector('.hfd-grossnet-n').textContent = sg(TOT.l - TOT.s, 1) + '%';
  root.querySelector('.hfd-grossnet-l').textContent = TOT.l.toFixed(1) + '%';
  root.querySelector('.hfd-grossnet-s').textContent = '-' + TOT.s.toFixed(1) + '%';
  root.querySelector('.hfd-grossnet-r').textContent = (TOT.l / TOT.s).toFixed(2) + 'x';
}
function sort() {
  var m = MODES[mi];
  rows.slice().sort(function (a, b) {
    if (m === 'GROSS') return gross(b) - gross(a);
    if (m === 'NET') return net(b) - net(a);
    if (m === 'LONG') return d(b, 'l') - d(a, 'l');
    return d(b, 'h') - d(a, 'h');
  }).forEach(function (r) { body.appendChild(r); });
}
function pick(r) {
  rows.forEach(function (x) { x.classList.toggle('hfd-grossnet-on', x === r); });
  var n = net(r), g = gross(r);
  rd.textContent = r.getAttribute('data-s') + '  L ' + d(r, 'l').toFixed(1) +
    ' / S -' + d(r, 'h').toFixed(1) + '  NET ' + sg(n, 1) +
    '  GROSS ' + g.toFixed(1) + '  ' + (g / TG * 100).toFixed(1) + '% OF GROSS';
}
rows.forEach(function (r) {
  r.addEventListener('click', function () { pick(r); });
  r.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(r); }
  });
});
btn.addEventListener('click', function () {
  mi = (mi + 1) % MODES.length;
  btn.textContent = MODES[mi];
  sort();
});
sort();
paint();

