var M = [100.00,101.42,102.87,101.60,103.84,105.21,106.94,105.13,103.40,106.82,108.91,110.44,
112.70,111.23,108.31,104.62,101.90,105.74,109.18,112.63,114.82,113.07,116.41,119.72,
121.34,123.81,122.10,125.63,128.94,127.42,130.81,133.52,131.24,128.37,132.68,136.91,
139.40,137.82,141.63,145.19,148.72,146.30,150.84,154.13,157.60,155.24,159.81,163.42,
166.10,164.23,168.71,172.38,175.94,173.11,178.62,181.20,184.73,181.94,178.60,179.81];
var MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
function label(i) { var t = 8 + i; return MON[t % 12] + '-' + String(21 + Math.floor(t / 12)).slice(-2); }
var hwm = [], dd = [], pk = -1e9, maxDD = 0, maxAt = 0;
M.forEach(function (v, i) {
  if (v > pk) pk = v;
  hwm.push(pk);
  var x = (v / pk - 1) * 100;
  dd.push(x);
  if (x < maxDD) { maxDD = x; maxAt = i; }
});
var lo = 96, hi = 190, W = 300, H1 = 54, H2 = 26, DDS = 10;
function px(i) { return i / (M.length - 1) * W; }
function py(v) { return H1 - (v - lo) / (hi - lo) * H1; }
function dy(v) { return Math.min(Math.abs(v) / DDS, 1) * H2; }
function line(a, f) {
  return a.map(function (v, i) { return (i ? 'L' : 'M') + px(i).toFixed(2) + ' ' + f(v).toFixed(2); }).join(' ');
}
root.querySelector('.hfd-ddhwm-nv').setAttribute('d', line(M, py));
root.querySelector('.hfd-ddhwm-hw').setAttribute('d', line(hwm, py));
root.querySelector('.hfd-ddhwm-uw').setAttribute('d',
  'M0 0 ' + dd.map(function (v, i) { return 'L' + px(i).toFixed(2) + ' ' + dy(v).toFixed(2); }).join(' ') + ' L' + W + ' 0 Z');
var last = M.length - 1;
var hwmIdx = hwm.lastIndexOf(hwm[last]);
var firstAtPeak = M.indexOf(hwm[last]);
root.querySelector('.hfd-ddhwm-cd').textContent = dd[last].toFixed(2) + '%';
root.querySelector('.hfd-ddhwm-md').textContent = maxDD.toFixed(2) + '%';
root.querySelector('.hfd-ddhwm-uwm').textContent = String(last - firstAtPeak);
root.querySelector('.hfd-ddhwm-tr').textContent = '+' + ((hwm[last] / M[last] - 1) * 100).toFixed(2) + '%';
var chart = root.querySelector('.hfd-ddhwm-chart');
var cx = root.querySelector('.hfd-ddhwm-cx');
var r1 = root.querySelector('.hfd-ddhwm-r1'), r2 = root.querySelector('.hfd-ddhwm-r2');
var r3 = root.querySelector('.hfd-ddhwm-r3'), r4 = root.querySelector('.hfd-ddhwm-r4');
var cur = last;
function show(i) {
  cur = Math.max(0, Math.min(M.length - 1, i));
  cx.style.left = (cur / (M.length - 1) * 100).toFixed(3) + '%';
  r1.textContent = label(cur);
  r2.textContent = 'NAV ' + M[cur].toFixed(2);
  r3.textContent = 'HWM ' + hwm[cur].toFixed(2);
  r4.textContent = 'DD ' + dd[cur].toFixed(2) + '%';
}
chart.addEventListener('pointermove', function (e) {
  var b = chart.getBoundingClientRect();
  if (!b.width) return;
  show(Math.round((e.clientX - b.left) / b.width * (M.length - 1)));
});
chart.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowLeft') { e.preventDefault(); show(cur - 1); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); show(cur + 1); }
  else if (e.key === 'Home') { e.preventDefault(); show(0); }
  else if (e.key === 'End') { e.preventDefault(); show(M.length - 1); }
  else if (e.key === 'd' || e.key === 'D') { e.preventDefault(); show(maxAt); }
});
show(last);

