  var s = parseFloat(sl.value);
  var gain = Math.max(0, G * (1 + s / 100) - HWM);
  var acc = gain * 0.20;
  sv.textContent = (s >= 0 ? '+' : '-') + Math.abs(s).toFixed(2) + '%';
  ua.textContent = money(acc);
  go.textContent = money(gain);
  dr.textContent = (acc > 0 ? '-' : '') + (acc / UNITS).toFixed(2);
  var tot = CRY + acc;
  cry.style.width = (CRY / tot * 100).toFixed(2) + '%';
  unr.style.width = (acc / tot * 100).toFixed(2) + '%';
  ua.style.color = acc > 0 ? '' : '#79839a';
}
sl.addEventListener('input', calc);
calc();

