var STEPS = ['NOTICE', 'AML', 'APPROVED', 'SETTLED'];
var Q = [
  { n: 'NORDIC SOVEREIGN WEALTH', t: 'S', c: 'C', a: 40000000, s: 2 },
  { n: 'HARBOURVIEW PENSION FD', t: 'S', c: 'C', a: 25000000, s: 2 },
  { n: 'MEIJI LIFE (SEG)', t: 'S', c: 'D', a: 12000000, s: 0 },
  { n: 'ALDERMAN FOUNDATION', t: 'S', c: 'F', a: 6250000, s: 2 },
  { n: 'KESTREL FAMILY OFFICE', t: 'S', c: 'A', a: 4500000, s: 1 },
  { n: 'TRIDENT MULTI-STRAT', t: 'R', c: 'B', a: -22750000, s: 2 },
  { n: 'CALDER UNIV ENDOWMENT', t: 'R', c: 'A', a: -15400000, s: -1, def: 5800000 },
  { n: 'BRIDGEWOOD ENDOWMENT', t: 'R', c: 'A', a: -8000000, s: 2 },
  { n: 'OAKLINE SPV II', t: 'R', c: 'C', a: -5600000, s: 0 },
  { n: 'PARKHILL WEALTH', t: 'R', c: 'A', a: -3100000, s: 3 }
];
var body = root.querySelector('.hfd-flowq-body');
var rd = root.querySelector('.hfd-flowq-rd');
var sel = 0;
function m2(n) { return (n < 0 ? '-' : '+') + (Math.abs(n) / 1e6).toFixed(2) + 'M'; }
function money(n) {
  return (n < 0 ? '-' : '+') + Math.abs(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}
function sp(cls, txt) { var s = document.createElement('span'); s.className = cls; s.textContent = txt; return s; }
function statusOf(r) { return r.s < 0 ? 'GATED' : STEPS[r.s]; }
function render() {
  body.textContent = '';
  Q.forEach(function (r, i) {
    var el = document.createElement('div');
    el.className = 'hfd-flowq-row ' + (r.t === 'S' ? 'hfd-flowq-issub' : 'hfd-flowq-isred') +
      (i === sel ? ' hfd-flowq-sel' : '');
    el.setAttribute('role', 'option');
    el.setAttribute('aria-selected', i === sel ? 'true' : 'false');
    el.appendChild(sp('hfd-flowq-nm', r.n));
    el.appendChild(sp('hfd-flowq-ty ' + (r.t === 'S' ? 'hfd-flowq-sub' : 'hfd-flowq-red'), r.t === 'S' ? 'S' : 'R'));
    el.appendChild(sp('hfd-flowq-cl', r.c));
    el.appendChild(sp('hfd-flowq-am', money(r.a)));
    el.appendChild(sp('hfd-flowq-st ' + (r.s < 0 ? 'hfd-flowq-sg' : 'hfd-flowq-s' + r.s), statusOf(r)));
    el.addEventListener('click', function () { sel = i; render(); describe(); });
    body.appendChild(el);
  });
  totals();
}
function totals() {
  var subs = 0, reds = 0, def = 0, appr = 0, apprAmt = 0;
  Q.forEach(function (r) {
    if (r.a >= 0) subs += r.a; else reds += -r.a;
    if (r.s < 0 && r.def) def += r.def;
    if (r.s >= 2) { appr++; apprAmt += r.a; }
  });
  root.querySelector('.hfd-flowq-fs').textContent = '+' + (subs / 1e6).toFixed(2) + 'M';
  root.querySelector('.hfd-flowq-fr').textContent = '-' + (reds / 1e6).toFixed(2) + 'M';
  root.querySelector('.hfd-flowq-fn').textContent = m2(subs - reds);
  root.querySelector('.hfd-flowq-fa').textContent = appr + '/' + Q.length;
  root.querySelector('.hfd-flowq-ft2').textContent =
    'AFTER GATE ' + m2(subs - reds + def) + ' · DEFERRED ' + (def / 1e6).toFixed(2) +
    'M · CLEARED NET ' + m2(apprAmt);
}
function describe(msg) {
  var r = Q[sel];
  rd.textContent = msg || (r.n + '  ' + (r.t === 'S' ? 'SUB' : 'RED') + ' CL ' + r.c +
    '  ' + money(r.a) + '  ' + statusOf(r));
}
function advance() {
  var r = Q[sel];
  if (r.s < 0) {
    var el = body.children[sel];
    el.classList.remove('hfd-flowq-shake');
    void el.offsetWidth;
    el.classList.add('hfd-flowq-shake');
    describe('GATE 25% OF CAPITAL ACCOUNT — 9,600,000 PAYABLE, 5,800,000 DEFERRED');
    return;
  }
  if (r.s >= STEPS.length - 1) { describe(r.n + '  ALREADY SETTLED — NO FURTHER ACTION'); return; }
  var from = STEPS[r.s];
  r.s++;
  render();
  describe(r.n + '  ' + from + ' → ' + STEPS[r.s]);
}
function move(d) {
  sel = Math.max(0, Math.min(Q.length - 1, sel + d));
  render();
  describe();
  var el = body.children[sel];
  if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest' });
}
body.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowDown') { e.preventDefault(); move(1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
  else if (e.key === 'Home') { e.preventDefault(); sel = 0; render(); describe(); }
  else if (e.key === 'End') { e.preventDefault(); sel = Q.length - 1; render(); describe(); }
  else if (e.key === 'Enter') { e.preventDefault(); advance(); }
});
render();

