var LEGS = [
  { n: 'EQ L/S TECH', b: 624, a: 28.4 },
  { n: 'EQ L/S HEALTH', b: 388, a: 19.2 },
  { n: 'MERGER ARB', b: 214, a: 12.6 },
  { n: 'CREDIT STRESSED', b: 186, a: 14.8 },
  { n: 'VOL ARB', b: 131, a: 8.4 },
  { n: 'CASH / TSY', b: 98, a: 9.1 },
  { n: 'MACRO RATES', b: -71, a: 4.7 },
  { n: 'FX OVERLAY', b: 46, a: 2.8 },
  { n: 'GROSS RETURN', sub: 1 },
  { n: 'FINANCING / BORROW', b: -46, fee: 1 },
  { n: 'MGMT FEE 150BP', b: -100, fee: 1 },
  { n: 'PERF FEE ACCRUAL', b: -290, fee: 1 },
  { n: 'FUND EXPENSES', b: -18, fee: 1 },
  { n: 'NET RETURN', sub: 1 }
];
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var body = root.querySelector('.hfd-attrib-body');
var rd = root.querySelector('.hfd-attrib-rd');
var btn = root.querySelector('.hfd-attrib-tog');
var MODES = ['BPS', 'ROC', 'CAP'];
var mi = 0;
var run = 0, gross = 0, fees = 0;
LEGS.forEach(function (l) {
  if (l.sub) { l.from = 0; l.to = run; l.total = run; return; }
  l.from = run; run += l.b; l.to = run;
  if (l.fee) fees += l.b; else gross += l.b;
});
var SC = 1700;
function pc(v) { return Math.max(0, Math.min(100, v / SC * 100)); }
function sg(v, d) { return (v >= 0 ? '+' : '-') + Math.abs(v).toFixed(d); }
function sp(cls, txt) { var s = document.createElement('span'); s.className = cls; s.textContent = txt; return s; }
root.querySelector('.hfd-attrib-cg').textContent = sg(gross / 100, 2) + '%';
root.querySelector('.hfd-attrib-cf').textContent = sg(fees / 100, 2) + '%';
root.querySelector('.hfd-attrib-cn').textContent = sg((gross + fees) / 100, 2) + '%';
function cellText(l) {
  if (l.sub) return sg(l.total, 0);
  if (MODES[mi] === 'BPS') return sg(l.b, 0);
  if (MODES[mi] === 'ROC') return l.a ? sg(l.b / l.a, 2) + '%' : '—';
  return l.a ? l.a.toFixed(1) : '—';
}
var rowEls = [];
LEGS.forEach(function (l, i) {
  var el = document.createElement('div');
  var cls = 'hfd-attrib-row';
  if (l.sub) cls += ' hfd-attrib-sub';
  else if (l.fee) cls += ' hfd-attrib-fee';
  else cls += l.b >= 0 ? ' hfd-attrib-pos' : ' hfd-attrib-neg';
  el.className = cls;
  el.tabIndex = 0;
  el.appendChild(sp('hfd-attrib-nm', l.n));
  var tk = document.createElement('span');
  tk.className = 'hfd-attrib-tk';
  var bar = document.createElement('i');
  bar.className = 'hfd-attrib-bar';
  var conn = document.createElement('i');
  conn.className = 'hfd-attrib-conn';
  conn.style.left = pc(l.sub ? l.total : l.from).toFixed(2) + '%';
  tk.appendChild(bar); tk.appendChild(conn);
  el.appendChild(tk);
  el.appendChild(sp('hfd-attrib-vv', cellText(l)));
  var lo = Math.min(l.from, l.to), hi = Math.max(l.from, l.to);
  function draw() {
    bar.style.left = pc(l.sub ? 0 : lo).toFixed(2) + '%';
    bar.style.width = (pc(l.sub ? l.total : hi) - pc(l.sub ? 0 : lo)).toFixed(2) + '%';
  }
  if (reduce) draw(); else setTimeout(function () { if (root.isConnected) draw(); }, 60 + i * 45);
  function info() {
    if (l.sub) { rd.textContent = l.n + '  ' + sg(l.total, 0) + ' BPS  =  ' + sg(l.total / 100, 2) + '% OF NAV'; return; }
    rd.textContent = l.n + '  ' + sg(l.b, 0) + ' BPS' +
      (l.a ? '  AVG CAP ' + l.a.toFixed(1) + '%  ROC ' + sg(l.b / l.a, 2) + '%' : '  FEE / FINANCING LEG') +
      '  CUM ' + sg(l.to, 0);
  }
  el.addEventListener('mouseenter', info);
  el.addEventListener('focus', info);
  rowEls.push({ el: el, l: l });
  body.appendChild(el);
});
btn.addEventListener('click', function () {
  mi = (mi + 1) % MODES.length;
  btn.textContent = MODES[mi];
  rowEls.forEach(function (r) {
    r.el.querySelector('.hfd-attrib-vv').textContent = cellText(r.l);
  });
});
